export const rateFor = (m) => {
  const netPerCycle = m.payout - m.cost;
  const perHour = Math.round(netPerCycle / m.minutes * 60);
  return {
    method: m,
    netPerCycle,
    perHour,
    perHourPerPlayer: Math.round(perHour / m.players)
  };
};
export const rankedMethods = () => METHODS.map(rateFor).sort((a, b) => b.perHour - a.perHour);
export const findMethod = (id) => METHODS.find((m) => m.id === id);
export function planGrind(method, goal, balance, sessionHours) {
  const { perHour, netPerCycle } = rateFor(method);
  const remaining = Math.max(0, goal - balance);
  const cycles = netPerCycle > 0 ? Math.ceil(remaining / netPerCycle) : 0;
  const hours = perHour > 0 ? remaining / perHour : 0;
  const session = Math.max(0.25, sessionHours);
  return {
    perHour,
    netPerCycle,
    cycles,
    hours: Math.round(hours * 10) / 10,
    days: Math.round(hours / 24 * 10) / 10,
    sessionsNeeded: Math.ceil(hours / session),
    remaining
  };
}
